"""Build one offline progress/results page from saved stage receipts."""
import json
import shutil
import sys
from pathlib import Path

root = Path(sys.argv[1])
out = root / "reports"
out.mkdir(exist_ok=True)
gate = json.loads((root / "contracts/gate.json").read_text())
coverage = json.loads((root / "contracts/coverage.json").read_text())
for name in ("gate.json", "coverage.json", "contracts.json"):
    shutil.copyfile(root / "contracts" / name, out / name)
stages = []
for folder in sorted(out.iterdir()):
    if not folder.is_dir() or not (folder / "summary.json").exists():
        continue
    s = json.loads((folder / "summary.json").read_text())
    m = json.loads((folder / "manifest.json").read_text())
    stages.append({"name": folder.name, "summary": s, "revision": m["revision"], "digest": m["sourceDigest"],
                   "baseline": m["baselineRevision"], "opponent": m.get("opponent", "planner"), "context": m.get("context", "exhibition")})
data = {"gate": gate, "coverage": coverage, "stages": stages}
(out / "lab-summary.json").write_text(json.dumps(data, indent=2))
page = '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sevens AI policy lab</title>
<style>:root{color-scheme:dark;background:#10151e;color:#edf2f8;font:16px/1.55 system-ui;--card:#192332;--muted:#b5c5d7;--line:#3b4d65;--blue:#8cc7ff;--green:#8ce5bd}*{box-sizing:border-box}body{max-width:1100px;margin:auto;padding:30px 22px 60px}h1{font-size:clamp(28px,5vw,43px);line-height:1.15}h2{font-size:22px;margin-top:32px}p{max-width:82ch}.muted,small{color:var(--muted)}.flow,.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:12px}.card,section{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:18px;margin:14px 0}.card strong{display:block;font-size:25px;color:var(--green)}.flow b{display:block;color:var(--blue)}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:9px 10px 9px 0;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}a{color:var(--blue)}.scroll{overflow-x:auto}button,input,select{font:inherit;background:#101b2c;color:#edf2f8;border:1px solid #5a718c;border-radius:7px;padding:8px;max-width:100%}svg{display:block;width:100%;height:230px}.tag{color:#ffd18e}code{overflow-wrap:anywhere;font-size:12px}.links{display:flex;flex-wrap:wrap;gap:15px}.gap{color:#ffd18e}</style>
<p class="muted">Blood Bowl Sevens · Daily Driver · saved evidence</p><h1>Prove a useful play.<br>Then measure the policy.</h1>
<p>Six-turn halves, seven players and separated starting lines. The shared planner values runs, transfers, hits and support. Capability modules add Vampire feeding, Gaze and other supported actions. Team labels do not dictate whether a particular opponent is worth hitting.</p>
<div class="flow"><div class="card"><b>1. Tactical contracts</b>Useful play and better-alternative controls through real engine commands.</div><div class="card"><b>2. Balanced pilot</b>Stop for rejected commands, incomplete blocks or replay differences.</div><div class="card"><b>3. Fresh confirmation</b>Freeze source and seeds. Balance roster, side and first receiver.</div><div class="card"><b>4. Inspect and extend</b>Read decision receipts and open skill gaps before changing policy.</div></div>
<div class="metrics" id="metrics"></div><h2>Policy results</h2><p class="muted">Points share counts a win as 1 and a draw as ½. Bars show 95% intervals from 2,000 resamples of complete eight-game blocks. A 50% result is parity. The pilot is diagnostic evidence and stays separate from confirmation.</p><svg id="chart" role="img" aria-label="Points share and confidence intervals"></svg><div class="scroll"><table><thead><tr><th>Stage</th><th>Games</th><th>Points share</th><th>Equal-roster share</th><th>Accepted passes</th><th>Deaths, AI / opponent</th></tr></thead><tbody id="stages"></tbody></table></div>
<h2>Team builds</h2><p>Coverage builds remain stress tests. Coherent builds assign distinct handler, passer, receiver and hitter jobs. Real Random Primary builds use the game's two offered rolls and actual prices. Both new development arms grant 12 SPP to each selected player; spent SPP and team value can differ. Comparisons within each arm pit both policies against the same builds.</p><div class="scroll"><table><thead><tr><th>Build method</th><th>Games</th><th>Points share</th><th>95% interval</th></tr></thead><tbody id="methods"></tbody></table></div>
<h2>Every roster stays visible</h2><select id="stage"></select><div class="scroll"><table><thead><tr><th>Roster</th><th>Games</th><th>Points share</th><th>TD difference / game</th><th>Turnover difference / game</th></tr></thead><tbody id="rosters"></tbody></table></div>
<h2>Skill evidence and open work</h2><p id="coverageNote"></p><details><summary>Search all 108 skills and traits</summary><input id="filter" type="search" placeholder="Find a skill or trait" aria-label="Filter skills"><div class="scroll"><table><thead><tr><th>Skill</th><th>Rule configurations</th><th>AI evidence</th></tr></thead><tbody id="skills"></tbody></table></div></details>
<section><h2>What the counts mean</h2><p>Legal declarations and planner proposals count repeated appearances in decision states. They are diagnostic denominators, not independently proved opportunities. Named tactical contracts provide that independent test. A selected pass declaration must still reach an accepted throw and a useful endpoint. Match pass counts alone do not prove good decisions.</p><p>Immediate-contact injury pricing uses actual Strength, assists, armour and player value. Persistent fixtures enable season-loss costs but restart teams between matches. They do not measure a whole career. The scoring horizon is a bounded geometry model, so defensive mode does not prove that every imaginable scoring chain is impossible.</p><p>Source archives and raw replay traces stay beside the acquisition on Daily Driver. Frozen opponents share the candidate engine and legal command list. New Hard/Legend policies share proposal ancestry too; neither is a fully independent tactical oracle. A team-level result does not isolate the value of a particular skill.</p></section>
<h2>Evidence</h2><p class="links"><a href="lab-summary.json">Lab summary</a><a href="gate.json">Tactical gate</a><a href="coverage.json">All skill contracts</a></p><div id="downloads"></div><p id="source" class="muted"></p>
<script>const D=__DATA__;const $=id=>document.getElementById(id);const pct=n=>n==null?'—':(n*100).toFixed(2)+'%';const ci=v=>v?v.map(pct).join(' to '):'—';const add=(id,vals)=>{const tr=document.createElement('tr');for(const v of vals){const td=document.createElement('td');td.textContent=v;tr.append(td)}$(id).append(tr)};
const confirm=D.stages.find(x=>x.name==='confirmation');const total=D.stages.reduce((n,x)=>n+x.summary.included,0);for(const [n,label] of [[D.gate.tests,'tactical checks'],[total.toLocaleString(),'saved match results'],[D.stages.reduce((n,x)=>n+x.summary.accepted_candidate_passes,0),'accepted AI passes'],[D.coverage.filter(x=>x.status==='open-tactical-gap').length,'open skill contracts']]){const c=document.createElement('div');c.className='card';const b=document.createElement('strong');b.textContent=n;c.append(b,document.createTextNode(label));$('metrics').append(c)}
for(const st of D.stages){const s=st.summary,c=s.comparisons.overall;add('stages',[st.name+' · '+st.context,c.games,pct(c.points)+' ['+ci(c.ci)+']',pct(s.equal_roster.points)+' ['+ci(s.equal_roster.ci)+']',s.accepted_candidate_passes,s.totals.candidate.deaths+' / '+s.totals.frozen.deaths]);const opt=document.createElement('option');opt.value=st.name;opt.textContent=st.name;$('stage').append(opt);const p=document.createElement('p');p.className='links';for(const [file,label] of [['policy-study-data.zip','Data ZIP'],['summary.json','Summary'],['decision-receipts.json','Decision receipts'],['manifest.json','Manifest'],['provenance.json','Digests']]){const a=document.createElement('a');a.href=st.name+'/'+file;a.textContent=st.name+': '+label;p.append(a)}$('downloads').append(p)}
for(const [name,c] of Object.entries((confirm||D.stages[0])?.summary.build_methods||{}))add('methods',[name,c.games,pct(c.points),ci(c.ci)]);
function roster(){const st=D.stages.find(x=>x.name===$('stage').value);$('rosters').replaceChildren();for(const r of st?.summary.rosters||[])add('rosters',[r.roster,r.games_per_policy,pct(r.points),r.touchdowns_delta.toFixed(3),r.turnovers_delta.toFixed(3)])}$('stage').value=confirm?'confirmation':D.stages[0]?.name;$('stage').onchange=roster;roster();
$('coverageNote').textContent=D.coverage.length+' catalogue entries; '+D.coverage.filter(x=>x.status==='bounded-contract').length+' have bounded AI contracts. Forced scenarios remain mechanical evidence. Open entries require a useful tactical case and a control before they can be called covered.';function skills(){$('skills').replaceChildren();for(const s of D.coverage.filter(x=>x.skill.toLowerCase().includes($('filter').value.toLowerCase())))add('skills',[s.skill,s.mechanics.length,s.aiContracts.join('; ')||'Open tactical gap'])}$('filter').oninput=skills;skills();
const svg=$('chart'),ns='http://www.w3.org/2000/svg';svg.setAttribute('viewBox','0 0 760 230');function draw(tag,attrs,text){const n=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,v);if(text)n.textContent=text;svg.append(n)}const x=p=>160+p*560;for(const p of [.25,.5,.75]){draw('line',{x1:x(p),x2:x(p),y1:15,y2:196,stroke:p===.5?'#8cc7ff':'#3b4d65','stroke-dasharray':'4 4'});draw('text',{x:x(p),y:220,fill:'#b5c5d7','text-anchor':'middle','font-size':14},pct(p))}D.stages.forEach((st,i)=>{const y=40+i*48,c=st.summary.comparisons.overall;draw('text',{x:5,y:y+5,fill:'#edf2f8','font-size':14},st.name);if(c.ci)draw('line',{x1:x(c.ci[0]),x2:x(c.ci[1]),y1:y,y2:y,stroke:'#8ce5bd','stroke-width':4});if(c.points!=null)draw('circle',{cx:x(c.points),cy:y,r:5,fill:'#8ce5bd'})});$('source').textContent=confirm?'Candidate '+confirm.revision+' · source SHA-256 '+confirm.digest:'Confirmation pending. Pilot results are diagnostic.';
</script></html>'''
(out / "index.html").write_text(page.replace("__DATA__", json.dumps(data).replace("<", "\\u003c")))
print(json.dumps({"report": str(out), "stages": [s["name"] for s in stages], "matches": sum(s["summary"]["included"] for s in stages)}))
